import React, { useState, useEffect } from 'react';
import axios from 'axios';

const BACKEND_URL = 'http://localhost:5000'; // Adjust if needed

const Dashboard = () => {
  const token = localStorage.getItem('token');

  const [skills, setSkills] = useState([]);
  const [mode, setMode] = useState('list'); // Default to list
  const [currentSkillName, setCurrentSkillName] = useState('');
  const [relatedSubSkills, setRelatedSubSkills] = useState([]);
  const [aiSuggestion, setAiSuggestion] = useState('');
  const [editingSkillId, setEditingSkillId] = useState(null);

  useEffect(() => {
    fetchSkills();
  }, []);

  const fetchSkills = async () => {
    try {
      const res = await axios.get(`${BACKEND_URL}/api/skills`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setSkills(res.data);
    } catch (err) {
      console.error('Failed to fetch skills:', err);
    }
  };

  const handleAddSkillName = () => {
    if (!currentSkillName.trim()) {
      alert('Please enter a skill name');
      return;
    }
    fetchRelatedSubSkills(currentSkillName.trim());
  };

  const fetchRelatedSubSkills = async (skillName) => {
    try {
      const res = await axios.post(
        `${BACKEND_URL}/api/openai/getRelatedSkills`,
        { skillName },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      const related = res.data.relatedSkills || [];
      if (related.length === 0) {
        alert('No related skills found from AI. Try a different skill.');
        return;
      }

      const initialSubs = related.map(name => ({ name, level: 5 }));
      setRelatedSubSkills(initialSubs);
      setAiSuggestion('');
      setMode('questionnaire');
      setEditingSkillId(null);
    } catch (error) {
      console.error('Error fetching related sub-skills:', error);
      alert('Failed to get related skills from AI.');
    }
  };

  const handleSubSkillLevelChange = (index, newLevel) => {
    const updatedSubs = [...relatedSubSkills];
    updatedSubs[index].level = Number(newLevel);
    setRelatedSubSkills(updatedSubs);
  };

  const handleQuestionnaireSubmit = async () => {
    try {
      const payload = {
        skillName: currentSkillName,
        subSkills: relatedSubSkills,
      };

      const res = await axios.post(
        `${BACKEND_URL}/api/openai/analyzeSkillLevels`,
        payload,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      const { suggestion, overallProgress } = res.data;

      setAiSuggestion(suggestion || 'No suggestions available.');

      if (editingSkillId) {
        await axios.put(
          `${BACKEND_URL}/api/skills/${editingSkillId}`,
          { name: currentSkillName, progress: overallProgress, subSkills: relatedSubSkills },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      } else {
        await axios.post(
          `${BACKEND_URL}/api/skills`,
          { name: currentSkillName, progress: overallProgress, subSkills: relatedSubSkills },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      }

      setMode('list');
      setCurrentSkillName('');
      setRelatedSubSkills([]);
      setEditingSkillId(null);
      fetchSkills();
    } catch (error) {
      console.error('Error submitting questionnaire:', error);
      alert('Failed to submit skill levels and get suggestions.');
    }
  };

  const handleEditSkill = async (skill) => {
    setCurrentSkillName(skill.name);
    setEditingSkillId(skill.id);
    setAiSuggestion('');
    const subSkills = skill.subSkills || [];

    if (subSkills.length > 0) {
      setRelatedSubSkills(subSkills);
      setMode('questionnaire');
    } else {
      // fallback: fetch related sub-skills again
      try {
        const res = await axios.post(
          `${BACKEND_URL}/api/openai/getRelatedSkills`,
          { skillName: skill.name },
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const related = res.data.relatedSkills || [];
        const initialSubs = related.map(name => ({ name, level: 5 }));
        setRelatedSubSkills(initialSubs);
        setMode('questionnaire');
      } catch (error) {
        alert('Failed to fetch related sub-skills for editing.');
        setMode('list');
      }
    }
  };

  const handleDeleteSkill = async (skillId) => {
    if (!window.confirm('Are you sure you want to delete this skill?')) return;

    try {
      await axios.delete(`${BACKEND_URL}/api/skills/${skillId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      fetchSkills(); // Refresh list
    } catch (error) {
      console.error('Failed to delete skill:', error);
      alert('Could not delete skill.');
    }
  };

  if (mode === 'addSkillName') {
    return (
      <div className="container" style={{ maxWidth: 600, marginTop: 40 }}>
        <h2>Add New Skill</h2>
        <input
          type="text"
          className="form-control mb-3"
          placeholder="Enter skill name"
          value={currentSkillName}
          onChange={e => setCurrentSkillName(e.target.value)}
        />
        <button className="btn btn-primary" onClick={handleAddSkillName}>
          Continue
        </button>
        <button
          className="btn btn-secondary ms-2"
          onClick={() => {
            setMode('list');
            setCurrentSkillName('');
          }}
        >
          Back to Skills
        </button>
      </div>
    );
  }

  if (mode === 'questionnaire') {
    return (
      <div className="container" style={{ maxWidth: 600, marginTop: 40 }}>
        <h2>Rate Sub-Skills for "{currentSkillName}"</h2>
        {relatedSubSkills.map((sub, idx) => (
          <div key={sub.name} className="mb-3">
            <label>
              {sub.name}: {sub.level}
            </label>
            <input
              type="range"
              min="1"
              max="10"
              value={sub.level}
              onChange={e => handleSubSkillLevelChange(idx, e.target.value)}
              className="form-range"
            />
          </div>
        ))}

        <button className="btn btn-success" onClick={handleQuestionnaireSubmit}>
          Submit & Get Suggestions
        </button>

        <button
          className="btn btn-secondary ms-2"
          onClick={() => {
            setMode('list');
            setCurrentSkillName('');
            setRelatedSubSkills([]);
          }}
        >
          Cancel
        </button>

        {aiSuggestion && (
          <div className="alert alert-info mt-4" style={{ whiteSpace: 'pre-wrap' }}>
            <strong>AI Suggestions:</strong>
            <br />
            {aiSuggestion}
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="container" style={{ maxWidth: 800, marginTop: 40 }}>
      <h2>Your Skills</h2>
      <button className="btn btn-link mb-3" onClick={() => setMode('addSkillName')}>
        + Add New Skill
      </button>

      {skills.length === 0 && <p>No skills yet. Add one above.</p>}

      <ul className="list-group">
        {skills.map(skill => (
          <li
            key={skill.id}
            className="list-group-item d-flex justify-content-between align-items-center"
          >
            <div style={{ flex: 1 }}>
              <strong>{skill.name}</strong>
              <div className="progress mt-1" style={{ height: '20px', width: '250px' }}>
                <div
                  className="progress-bar"
                  role="progressbar"
                  style={{ width: `${skill.progress}%` }}
                  aria-valuenow={skill.progress}
                  aria-valuemin="0"
                  aria-valuemax="100"
                >
                  {skill.progress}%
                </div>
              </div>
            </div>

            <div className="btn-group ms-3">
              <button
                className="btn btn-sm btn-outline-primary"
                onClick={() => handleEditSkill(skill)}
              >
                Edit
              </button>
              <button
                className="btn btn-sm btn-outline-danger"
                onClick={() => handleDeleteSkill(skill.id)}
              >
                Delete
              </button>
              <button
                className="btn btn-sm btn-outline-danger"
                onClick={() => handleAiSuggestionSkill(skill.id)}
              >
                AI Suggestions
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Dashboard;
